import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cd/cdd.md","filePath":"lezioni/c_analisi/cd/cdd.md"}`),a={name:`lezioni/c_analisi/cd/cdd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h2 id="l-infinito-nei-limiti" tabindex="-1">l&#39;infinito nei limiti <a class="header-anchor" href="#l-infinito-nei-limiti" aria-label="Permalink to “l&#39;infinito nei limiti”">​</a></h2><p>Il concetto di infinito è sempre stato un po&#39; la bestia nera della matematica e col concetto di limite si può affrontare in modo abbastanza efficace: il limite mi mette in relazione due intervalli che si contraggono contemporaneamente: allora perché non applicare questo concetto anche ad un intorno di infinito? Il problema è che non posso far riferimento ad un intorno e nemmeno ad un intervallo, però posso fare riferimento al bordo dell&#39;intervallo che, man mano che si <a href="./cdd1.html">stringe</a>, assumerà valori sempre più grandi in valore assoluto.</p><hr><p>In pratica quando ho un intervallo che si stringe verso infinito devo dire che il suo valore di bordo risulta maggiore di un qualunque numero (di solito indicato con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi></mrow><annotation encoding="application/x-tex">M</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> per le <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span> ed <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> per le <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>) grande a piacere se andiamo verso <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>+</mo><mi mathvariant="normal">∞</mi></mrow><annotation encoding="application/x-tex">+\\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">∞</span></span></span></span> oppure minore di un numero qualunque numero negativo grande a piacere in valore assoluto se ci spostiamo verso <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>−</mo><mi mathvariant="normal">∞</mi></mrow><annotation encoding="application/x-tex">-\\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">∞</span></span></span></span>.</p><p>Sarebbe bene che provassi ora a ricavare tu i vari casi senza studiarli a memoria, comunque, magari per esercizio, di seguito ti enumero i casi possibili:</p><hr><p>Distinguiamo tre casi:</p><ul><li><a href="./cdda.html"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>limite\xA0</mtext><mi mathvariant="normal">∞</mi><mtext>\xA0per\xA0</mtext><mi>x</mi><mo>→</mo><mi>c</mi></mrow><annotation encoding="application/x-tex">\\text{limite } \\infty \\text{ per } x \\to c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">limite\xA0</span></span><span class="mord">∞</span><span class="mord text"><span class="mord">\xA0per\xA0</span></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span></a></li><li><a href="./cddb.html"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>limite\xA0</mtext><mi>l</mi><mtext>\xA0per\xA0</mtext><mi>x</mi><mo>→</mo><mi mathvariant="normal">∞</mi></mrow><annotation encoding="application/x-tex">\\text{limite } l \\text{ per } x \\to \\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">limite\xA0</span></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord text"><span class="mord">\xA0per\xA0</span></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord">∞</span></span></span></span></a></li><li><a href="./cddc.html"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>limite\xA0</mtext><mi mathvariant="normal">∞</mi><mtext>\xA0per\xA0</mtext><mi>x</mi><mo>→</mo><mi mathvariant="normal">∞</mi></mrow><annotation encoding="application/x-tex">\\text{limite } \\infty \\text{ per } x \\to \\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">limite\xA0</span></span><span class="mord">∞</span><span class="mord text"><span class="mord">\xA0per\xA0</span></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord">∞</span></span></span></span></a></li></ul><p>Se vuoi puoi dare un&#39;occhiata alla <a href="./cdd0.html">tabella riassuntiva</a> dei vari casi altrimenti fai <a href="./cde.html">click qui per passare</a> ai teoremi sui limiti.</p><hr><p>C&#39;è ancora da dire che il concetto di limite mi permette di risolvere uno dei problemi più spinosi della matematica: <a href="./cdd1a.html">la divisione per zero</a>.</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};